sub _jm_re_9($$$)
{
    my ($val, $path, $rep) = @_;
    my $res = $val =~ /^((file|https?):\/\/.+|\.\/.*|\.\.\/.*)$/;
    return $res;
}

# check $Model#Url (.'$Model#Url')
sub json_model_4($$$)
{
    my ($val, $path, $rep) = @_;
    # .'$Model#Url'
    # "/^((file|https?)://.+|\\./.*|\\.\\./.*)$/"
    my $res = jm_is_string($val) && _jm_re_9($val, $path, $rep);
    push @$rep, ["unexpected value for model \"/^((file|https?)://.+|\\\\./.*|\\\\.\\\\./.*)\\\$/\" [.'\$Model#Url']", $path] if defined $rep and not $res;
    return $res;
}

sub _jm_re_10($$$)
{
