# initialization of global variables

our $initialized = 0;

sub check_model_init()
{
    if (!$initialized)
    {
        $initialized = 1;
        %_jm_cst_0 = (
            "\$DATE" => 1,
            "\$TIME" => 1,
            "\$DATETIME" => 1,
            "\$URL" => 1,
            "\$URI" => 1,
            "\$UUID" => 1,
            "\$EMAIL" => 1,
            "\$REGEX" => 1,
            "\$EXREG" => 1,
            "\$NULL" => 1,
            "\$BOOL" => 1,
            "\$FLOAT" => 1,
            "\$F16" => 1,
            "\$F32" => 1,
            "\$F64" => 1,
            "\$NUMBER" => 1,
            "\$INT" => 1,
            "\$INTEGER" => 1,
            "\$I8" => 1,
            "\$I16" => 1,
            "\$I32" => 1,
            "\$I64" => 1,
            "\$U8" => 1,
            "\$U16" => 1,
            "\$U32" => 1,
            "\$U64" => 1,
            "\$STRING" => 1,
            "\$NONE" => 1,
            "\$ANY" => 1,
        );
        %check_model_map = (
            "" => \&json_model_42,
            "Model" => \&json_model_42,
        );
    }
}

sub check_model_free()
{
    if ($initialized)
    {
        $initialized = 0;
        %_jm_cst_0 = ();
        %check_model_map = ();
    }
}

sub check_model_mapper($)
{
    my ($name) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    return $check_model_map{$name};
}

sub check_model($$$)
{
    my ($json, $name, $rep) = @_;
    die "unexpected model name \"$name\"" unless exists $check_model_map{$name};
    my $path = defined $rep ? [] : undef;
    return $check_model_map{$name}($json, $path, $rep);
}

#
# SCRIPT EXECUTION
#
check_model_init();
jm_main(\&check_model, \%check_model_map, JMC_VERSION);
check_model_free();
